export interface CalendarEvent {
  id: number;
  title: string;
  description: string;
  startDate: string;
  endDate: string;
  type: EventType;
  location?: string;
  onlineUrl?: string;
  status: EventStatus;
  organizerName?: string;
  assigneeName?: string;
  departmentName?: string;
  priority: number;
  color: string;
  createdAt: string;
  originalEntityId: number;
  eventTypeName: EventType;
  reminderTime?: string;
}

export interface CalendarEventResponse {
  success: boolean;
  message: string;
  data: CalendarEvent[];
  errors: string[];
}

export enum EventType {
  Meeting = 0,
  Task = 1,
  Visit = 2,
  Travel = 3,
}

export enum EventStatus {
  Scheduled = 0,
  InProgress = 1,
  Completed = 2,
  Cancelled = 3,
  Overdue = 4,
}

export interface CalendarFilters {
  type?: EventType;
  status?: EventStatus;
  search?: string;
}

export interface CalendarView {
  currentDate: Date;
  viewType: 'month' | 'week' | 'day';
}

export interface SimpleEvent {
  dayName: string;
  dateFormatted: string;
  subject: string;
  timeFormatted: string;
  location: string;
  assignedEmployeeName: string;
  eventTypeName: string;
  originalEntityId: number;
}

export interface SimpleEventsResponse {
  success: boolean;
  message: string;
  data: {
    events: SimpleEvent[];
    totalCount: number;
    fromDate: string;
    toDate: string;
    periodDescription: string;
  };
  errors: string[];
}
