import { Component, Input, OnInit, OnDestroy, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CalendarEvent, SimpleEvent } from '../../../models/calendar.model';
import { Reminder } from '../../../models/reminder.model';
import { TranslationService } from '../../../services/translation.service';
import { LangService } from '../../../services/lang.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-calendar-table-view',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './calendar-table-view.component.html',
  styleUrls: ['./calendar-table-view.component.css']
})
export class CalendarTableViewComponent implements OnInit, OnDestroy {
  @Input() events: CalendarEvent[] = [];
  @Input() simpleEvents: SimpleEvent[] = [];
  @Input() reminders: Reminder[] = [];
  
  isRTL = signal<boolean>(false);
  private subscriptions: Subscription[] = [];

  constructor(
    private translationService: TranslationService,
    private langService: LangService
  ) {}

  ngOnInit(): void {
    this.setupLanguageSubscription();
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((sub) => sub.unsubscribe());
  }

  private setupLanguageSubscription(): void {
    const langSub = this.langService.currentLang$.subscribe(
      (lang: 'ar' | 'en') => {
        this.isRTL.set(lang === 'ar');
      }
    );
    this.subscriptions.push(langSub);
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  getDayName(date: Date): string {
    if (this.isRTL()) {
      const dayNames = [
        'الأحد',
        'الاثنين',
        'الثلاثاء',
        'الأربعاء',
        'الخميس',
        'الجمعة',
        'السبت',
      ];
      return dayNames[date.getDay()];
    } else {
      const dayNames = [
        'Sunday',
        'Monday',
        'Tuesday',
        'Wednesday',
        'Thursday',
        'Friday',
        'Saturday',
      ];
      return dayNames[date.getDay()];
    }
  }

  getEventTypeLabel(type: number): string {
    const typeLabels = {
      0: 'meeting',
      1: 'task',
      2: 'visit',
      3: 'travel'
    };
    const key = typeLabels[type as keyof typeof typeLabels] || 'unknown';
    return this.translate(`calendar.event_types.${key}`);
  }

  getEventTypeFromName(typeName: string): number {
    const typeMap: { [key: string]: number } = {
      'اجتماع': 0, // meeting
      'مهمة': 1,   // task
      'زيارة': 2,  // visit
      'سفر': 3,    // travel
      'meeting': 0,
      'task': 1,
      'visit': 2,
      'travel': 3,
      'Meeting': 0,
      'Task': 1,
      'Visit': 2,
      'Travel': 3
    };
    return typeMap[typeName] || 0;
  }

  getEventStatusLabel(status: number): string {
    const statusLabels = {
      0: 'scheduled',
      1: 'in_progress',
      2: 'completed',
      3: 'cancelled',
      4: 'overdue'
    };
    const key = statusLabels[status as keyof typeof statusLabels] || 'unknown';
    return this.translate(`calendar.event_statuses.${key}`);
  }

  getEventStatusColor(status: number): string {
    const statusColors = {
      0: '#2196f3', // scheduled - blue
      1: '#ff9800', // in_progress - orange
      2: '#4caf50', // completed - green
      3: '#f44336', // cancelled - red
      4: '#9c27b0'  // overdue - purple
    };
    return statusColors[status as keyof typeof statusColors] || '#6c757d';
  }

  getEventTypeColor(type: number): string {
    const typeColors = {
      0: '#2196f3', // meeting - blue
      1: '#4caf50', // task - green
      2: '#ff9800', // visit - orange
      3: '#9c27b0'  // travel - purple
    };
    return typeColors[type as keyof typeof typeColors] || '#6c757d';
  }

  formatTime(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleDateString();
  }

  trackByFn(index: number, item: any): any {
    return item.id || index;
  }

  // Combine events and reminders into a single table data source
  getTableData(): any[] {
    const tableData: any[] = [];

    // If simple events are available, use only those (from new API)
    if (this.simpleEvents && this.simpleEvents.length > 0) {
      this.simpleEvents.forEach(simpleEvent => {
        const eventType = this.getEventTypeFromName(simpleEvent.eventTypeName);
        tableData.push({
          type: 'simpleEvent',
          id: simpleEvent.originalEntityId,
          day: simpleEvent.dayName,
          date: simpleEvent.dateFormatted,
          subject: simpleEvent.subject,
          time: simpleEvent.timeFormatted,
          location: simpleEvent.location || '-',
          assignedEmployee: simpleEvent.assignedEmployeeName || '-',
          status: 0, // scheduled by default
          eventType: eventType,
          description: '',
          startDate: simpleEvent.dateFormatted,
          endDate: simpleEvent.dateFormatted
        });
      });
      // Return only simple events, don't add reminders or regular events
      return tableData.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
    } else {
      // Fallback: combine regular events and reminders if simple events not available
      this.events.forEach(event => {
        tableData.push({
          type: 'event',
          id: event.id,
          day: this.getDayName(new Date(event.startDate)),
          date: this.formatDate(event.startDate),
          subject: event.title,
          time: this.formatTime(event.startDate),
          location: event.location || '-',
          assignedEmployee: event.assigneeName || '-',
          status: event.status,
          eventType: event.type,
          description: event.description,
          startDate: event.startDate,
          endDate: event.endDate
        });
      });

      // Add reminders only when not using simple events
      this.reminders.forEach(reminder => {
        tableData.push({
          type: 'reminder',
          id: reminder.id,
          day: this.getDayName(new Date(reminder.reminderTime)),
          date: this.formatDate(reminder.reminderTime),
          subject: reminder.title,
          time: this.formatTime(reminder.reminderTime),
          location: '-',
          assignedEmployee: '-',
          status: 0, // scheduled
          eventType: 0, // meeting
          description: reminder.description,
          startDate: reminder.reminderTime,
          endDate: reminder.reminderTime
        });
      });

      // Sort by date
      return tableData.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
    }
  }
}
