import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { CalendarEvent, CalendarEventResponse, EventType, EventStatus, SimpleEventsResponse } from '../models/calendar.model';

@Injectable({
  providedIn: 'root',
})
export class CalendarService {
  private baseUrl = environment.apiBaseUrl;

  constructor(private http: HttpClient) {}

  getUserEvents(): Observable<CalendarEventResponse> {
    return this.http.get<CalendarEventResponse>(`${this.baseUrl}/Calendar/user/events`);
  }

  getUserEventsSimple(): Observable<SimpleEventsResponse> {
    return this.http.get<SimpleEventsResponse>(`${this.baseUrl}/Calendar/user/events/simple`);
  }

  getSystemEvents(
    type?: EventType,
    status?: EventStatus,
    search?: string
  ): Observable<CalendarEventResponse> {
    let params = new HttpParams();

    if (type !== undefined) {
      params = params.set('type', type.toString());
    }
    if (status !== undefined) {
      params = params.set('status', status.toString());
    }
    if (search) {
      params = params.set('search', search);
    }

    return this.http.get<CalendarEventResponse>(`${this.baseUrl}/Calendar/system/events`, {
      params,
    });
  }

  getSystemEventsSimple(): Observable<SimpleEventsResponse> {
    return this.http.get<SimpleEventsResponse>(`${this.baseUrl}/Calendar/system/events/simple`);
  }

  getEventTypeLabel(type: EventType): string {
    switch (type) {
      case EventType.Meeting:
        return 'calendar.event_types.meeting';
      case EventType.Task:
        return 'calendar.event_types.task';
      case EventType.Visit:
        return 'calendar.event_types.visit';
      case EventType.Travel:
        return 'calendar.event_types.travel';
      default:
        return 'Unknown';
    }
  }

  getEventStatusLabel(status: EventStatus): string {
    switch (status) {
      case EventStatus.Scheduled:
        return 'calendar.event_statuses.scheduled';
      case EventStatus.InProgress:
        return 'calendar.event_statuses.in_progress';
      case EventStatus.Completed:
        return 'calendar.event_statuses.completed';
      case EventStatus.Cancelled:
        return 'calendar.event_statuses.cancelled';
      case EventStatus.Overdue:
        return 'calendar.event_statuses.overdue';
      default:
        return 'Unknown';
    }
  }

  getEventStatusColor(status: EventStatus): string {
    switch (status) {
      case EventStatus.Scheduled:
        return '#4285F4';
      case EventStatus.InProgress:
        return '#D87E37';
      case EventStatus.Completed:
        return '#34A853';
      case EventStatus.Cancelled:
        return '#EA4335';
      case EventStatus.Overdue:
        return '#FF6B6B';
      default:
        return '#6C757D';
    }
  }

  getPriorityColor(priority: number): string {
    switch (priority) {
      case 1:
        return '#34A853'; // High priority - Green
      case 2:
        return '#D87E37'; // Medium priority - Yellow
      case 3:
        return '#EA4335'; // Low priority - Red
      default:
        return '#6C757D'; // Default - Gray
    }
  }

  getEventTypeColor(type: EventType): string {
    switch (type) {
      case EventType.Meeting:
        return '#29ABE2'; 
      case EventType.Task:
        return '#D87E37'; 
      case EventType.Visit:
        return '#72444A'; 
      case EventType.Travel:
        return '#27AE60'; 
      default:
        return '#6C757D'; 
    }
  }
}
